function elementFull(x){const e=native(x).element||{};if(!e.grade)return '';const d=elements[e.applyType],steps=x.elementSteps,color=elementColor(e.applyType);return `<section class="element-refinement" style="--element:${color}"><div class="refinement-header"><span><img src="assets/${d?.[1]||'dark'}.png" alt="">${esc(d?.[0]||'Element')} <b>+${e.grade}</b>${steps?.verified?`<small class="element-inline-steps">(${steps.power.slice(0,e.grade).map(num).join(', ')})</small>`:''}</span></div><div class="refinement-totals"><span>Element gücü <strong>+${e.value}%</strong></span><span>Saldırı <strong>+${e.bonus||0}</strong></span></div>${native(x).absorption?'<small class="refinement-source">Emilen eşyadaki element değerleri</small>':''}</section>`}
function inlineAttackBonus(lines,index){return /^(?:Büyülü\s+)?saldırı değeri\s+\d+\s*[-–]\s*\d+/i.test(String(lines[index]).trim())&&/^\(\+\d+\)$/.test(String(lines[index+1]||'').trim())?String(lines[index+1]).trim():''}
function isJoinedAttackBonus(lines,index){return index>0&&!!inlineAttackBonus(lines,index-1)}
function tooltipLineOrder(lines,bonusTexts=new Set(),context={}){const order=lines.map((_,i)=>i).slice(1),type=context.ClientDetails?.itemType;if(type!=null&&![1,2,28].includes(type))return order;const elementPower=/^(?:Ateşin|Buzun|Rüzgarın|Toprağın|Karanlığın|Şimşeğin|Şimşeklerin) gücü\s*[+%\d]/i;const base=order.filter(i=>{const t=String(lines[i]).trim();return (context.socketTextStart==null||i<context.socketTextStart)&&!bonusTexts.has(t)&&(/^(?:Büyülü\s+)?saldırı değeri\s+\d+\s*[-–]\s*\d+/i.test(t)||/^(?:Saldırı Hızı|Hareket Hızı|Büyü Hızı|Defans|Savunma)\s*[:+%\d-]/i.test(t)||/^[+-]?%?\d+(?:[.,]\d+)?%?\s+(?:Saldırı|Hareket|Büyü) hızı\.?$/i.test(t)||(native(context).element?.grade&&elementPower.test(t)))});if(!base.length)return order;const power=base.filter(i=>elementPower.test(String(lines[i]).trim()));for(const i of power){base.splice(base.indexOf(i),1);const attack=base.findLastIndex(j=>/^(?:Büyülü\s+)?saldırı değeri/i.test(String(lines[j]).trim()));base.splice(attack>=0?attack+1:base.length,0,i)}const move=new Set(base);for(const i of base)if(/^\(\+\d+\)$/.test(String(lines[i+1]||'').trim())&&(context.socketTextStart==null||i+1<context.socketTextStart))move.add(i+1);const rest=order.filter(i=>!move.has(i));const anchor=rest.findIndex(i=>/^(?:Seviye\s*:|Minimum şampiyon seviyesi\s*:|Emiş oranı\s*:?)/i.test(String(lines[i]).trim()));if(anchor<0&&![1,2].includes(type))return order;rest.splice(anchor>=0?anchor+1:0,0,...base.flatMap(i=>move.has(i+1)&&!base.includes(i+1)?[i,i+1]:[i]));return rest}
function tooltipText(value){return esc(value).replace(/\\n|\r?\n/g,'<br>')}
function gameCard(x){
 const d=native(x),lines=d.lines||x.TooltipLines||[],calls=d.rendererCalls?.AppendTextLine||[],bonusTexts=new Set(bonuses(x).map(b=>b.text.trim())),base=[],extra=[];let previous=null,afterBonuses=false;
 const elementRoots={99:'Şimşek',100:'Ateş',101:'Buz',102:'Rüzgar',103:'Toprak',104:'Karanlık'},root=elementRoots[d.element?.applyType];
 for(const i of tooltipLineOrder(lines,bonusTexts,x)){
  const text=String(lines[i]).trim();
  if(isJoinedAttackBonus(lines,i)||(d.element?.grade&&text===((elements[d.element.applyType]?.[0]||'Element')+' +'+d.element.grade)))continue;
  if(!text||(x.socketTextStart!=null&&i>=x.socketTextStart)||text===previous||lines.slice(1,i).some(l=>String(l).trim()!==text&&String(l).trim().includes(text)&&!calls.some(c=>String(c[0]).trim()===text)))continue;
  previous=text;if(bonusTexts.has(text)){afterBonuses=true;continue}
  if(d.element?.grade&&root&&text.startsWith(root.slice(0,-1))&&/gücü\s*[+%\d]/i.test(text)&&!text.includes('Toplam'))continue;
  const c=calls.find(v=>String(v[0]).trim()===text),color=c&&typeof c[1]==='number'?'#'+((c[1]>>>0)&0xffffff).toString(16).padStart(6,'0'):null;
  const html=`<div class="game-line"${color?` style="color:${color}"`:''}>${tooltipText(text)}${inlineAttackBonus(lines,i)?` <span class="attack-inline-bonus">${esc(inlineAttackBonus(lines,i))}</span>`:''}</div>`;
  const usage=/^\[?\s*Giyilebilir|^(?:Savaşçı|Ninja|Sura|Şaman|Lycan)(?:\s|$)/i.test(text);
  (afterBonuses||usage?extra:base).push(html);
 }
 let basic=base.join('');if(x.special?.pet?.filled&&typeof petDetailPanel==='function')basic=petDetailPanel(x.special.pet);
 const bonusMarkup=bonuses(x).length?bonusGroups(x):'';
 return `<div class="game-card ordered-game-card">${icon(x)}<h3>${esc(title(x))}</h3>${basic?`<section class="game-basic game-lines" aria-label="Temel özellikler">${basic}</section>`:''}${elementFull(x)}${bonusMarkup?`<section class="game-bonuses" aria-label="Efsunlar">${bonusMarkup}</section>`:''}${stoneIcons(x)}${embeddedCard(x)}${extra.length&&!x.special?.pet?.filled?`<section class="game-extra game-lines" aria-label="Ek bilgiler">${extra.join('')}</section>`:''}${equipmentFeatures(x)}${!lines.length?'<div class="base-note">İstemcinin tam açıklama metni bu kayıtta bulunmuyor.</div>':''}${d.warnings?.length?`<div class="base-note">${d.warnings.map(esc).join('<br>')}</div>`:''}<div class="base-note">${esc(date(x.observed))} · ${esc(serverLabel())}</div></div>`;
}
function hideTooltip(){if(typeof hideAttachment==='function'&&!$('attachment-tooltip').matches(':hover,:focus-within'))hideAttachment();clearTimeout(hoverTimer);const box=$('hover-tooltip');if(box.matches(':popover-open'))box.hidePopover();box.hidden=true}
window.addEventListener('resize',hideTooltip,{passive:true});
document.addEventListener('pointerdown',e=>{if(!e.target.closest('[data-hover],#hover-tooltip'))hideTooltip()});
document.addEventListener('focusout',e=>{if(e.target.closest('[data-hover]')&&!e.relatedTarget?.closest('[data-hover],#hover-tooltip'))hideTooltip()});
function showTooltip(el,key){const x=itemsMap.get(key);if(!x)return;clearTimeout(hoverTimer);const box=$('hover-tooltip'),host=el.closest('dialog')||document.body;if(box.parentElement!==host){if(box.matches(':popover-open'))box.hidePopover();host.append(box);}box.innerHTML=gameCard(x)+`<div class="tooltip-foot"><button class="button" data-detail="${key}">Ayrıntıyı sabitle ↗</button></div>`;box.hidden=false;if(!box.matches(':popover-open'))box.showPopover();const r=el.getBoundingClientRect(),width=Math.min(380,document.documentElement.clientWidth-24);box.style.width=width+'px';let left=r.right+17;if(left+width>innerWidth-10)left=r.left-width-15;left=Math.max(12,Math.min(left,document.documentElement.clientWidth-width-12));box.style.left=left+'px';box.style.top=Math.max(10,Math.min(r.top,innerHeight-box.offsetHeight-12))+'px';box.scrollTop=0;}
document.addEventListener('pointerover',e=>{if(e.pointerType==='touch')return;const el=e.target.closest('[data-hover]');if(el&&!el.contains(e.relatedTarget))showTooltip(el,el.dataset.hover);if(e.target.closest('#hover-tooltip,#attachment-tooltip'))clearTimeout(hoverTimer)});
