document.addEventListener('focusin',e=>{const el=e.target.closest('[data-hover]');if(el)showTooltip(el,el.dataset.hover)});window.addEventListener('scroll',()=>{if(!document.activeElement?.matches('[data-hover]'))hideTooltip()},{passive:true});
async function details(key){const requestedServer=selectedServer;hideTooltip();const x=itemsMap.get(key)||await api('/api/item?id='+encodeURIComponent(key));if(requestedServer!==selectedServer)return;itemsMap.set(key,x);$('detail-content').innerHTML=compactDetail(x);if($('detail').open)$('detail').close();$('detail').showModal();initContainerDetails(x);const alternatives=$('detail-content').querySelector('.detail-alternatives');alternatives.addEventListener('toggle',()=>{if(alternatives.open&&!alternatives.dataset.loaded){alternatives.dataset.loaded='true';loadSimilar(x)}});}
async function loadSimilar(source){try{const data=await api('/api/similar?id='+encodeURIComponent(source.id)),host=$('similar-items');if(!host||host.dataset.source!==source.id)return;data.suggestions.forEach(r=>itemsMap.set(r.item.id,r.item));host.innerHTML=`<h3>Daha uygun alternatifler <b>${data.suggestions.length}</b></h3><p>Aynı model · Yakın efsun oranları · ${esc(serverLabel())}</p>${data.suggestions.map(r=>{const x=r.item,e=native(x).element||{};return `<article class="similar-card"><div class="similar-heading">${icon(x)}<div><button data-detail="${x.id}" class="similar-name">${esc(title(x))}</button><small>${esc(x.Seller)} · ${esc(date(x.observed))}</small></div><span class="saving-badge">%${num(r.savingPercent)} daha düşük</span></div><div class="similar-price"><strong>${esc(moneyText(unit(x)))}</strong><span>Adet başı ${esc(moneyText(r.saving))} fark</span></div><div class="similar-differences"><span>${r.nearbyBonuses}/${r.sourceBonuses} yakın efsun oranı</span>${r.sameQuality?`<span>Aynı simya kalitesi</span><span>${esc((native(x).lines||[]).find(l=>l.startsWith('Saflık:'))||'')}</span>`:`<span>${r.upgradeDifference===0?'Aynı yükseltme':'Yükseltme '+(r.upgradeDifference>0?'+':'')+r.upgradeDifference}</span><span>${r.sameElement?'Aynı element seviyesi':(elements[e.applyType]?.[0]||'Element yok')+(e.grade?' +'+e.grade:'')}</span>`}${r.differences.slice(0,2).map(d=>`<span>${esc(statLabel(effectsType(source,d)))}: ${d.current} → ${d.alternative}</span>`).join('')}</div><div class="similar-actions"><button class="text-button" data-detail="${x.id}">İncele ↗</button><button class="button" data-compare-pair="${source.id}|${x.id}">İkisini karşılaştır</button></div></article>`}).join('')||'<div class="similar-empty">Bu kayıtta benzer ve daha ucuz bir alternatif bulunamadı.</div>'}<small class="similar-note">Efsun değerleri farklı olabilir. Fiyat avantajı daha güçlü ekipman anlamına gelmez.</small>`}catch{const host=$('similar-items');if(host?.dataset.source===source.id)host.innerHTML='<h3>Daha uygun alternatifler</h3><p>Alternatif ilanlar şu anda yüklenemedi.</p>'}}
function effectsType(source,difference){return bonuses(source).find(b=>b.text===difference.label)?.type||''}
function toggleFavorite(key){favorites.has(key)?favorites.delete(key):favorites.add(key);try{localStorage.setItem('m2search-'+selectedServer+'-favorites',JSON.stringify([...favorites]))}catch{toast('Kaydetme bu oturumda tutuluyor.')}if(view==='favorites')load();else renderList();syncDetailActions()}
function toggleCompare(key){if(selected.includes(key))selected=selected.filter(k=>k!==key);else if(selected.length<3)selected.push(key);else return toast('En fazla 3 ilanı karşılaştırabilirsin.');renderList();syncDetailActions();toast(selected.includes(key)?'Karşılaştırmaya eklendi.':'Karşılaştırmadan çıkarıldı.')}
function comparisonBonusKey(x,b){return (native(x).itemType===29?'simya':b.slot>=5?'rare':'first')+'|'+b.type}
function comparisonBonuses(items){const keys=new Map();items.forEach(x=>bonuses(x).forEach(b=>{const key=comparisonBonusKey(x,b);if(!keys.has(key))keys.set(key,{key,type:b.type,group:native(x).itemType===29?'Simya':b.slot>=5?'6–7':'1–5'})}));return [...keys.values()]}
function comparisonBase(x){const d=native(x),b=new Set(bonuses(x).map(a=>a.text.trim()));const lines=d.lines||x.TooltipLines||[];return tooltipLineOrder(lines,b,x).filter(i=>lines[i].trim()&&!b.has(lines[i].trim())&&(x.socketTextStart==null||i<x.socketTextStart)).filter(i=>!isJoinedAttackBonus(lines,i)).map(i=>lines[i]+(inlineAttackBonus(lines,i)?' '+inlineAttackBonus(lines,i):'')).filter((t,i,arr)=>arr.findIndex(a=>a.trim()===t.trim())===i).map(t=>`<div class="comparison-base-line">${tooltipText(t)}</div>`).join('')||'<span class="comparison-missing">Kayıt yok</span>'}
async function compare(){if(selected.length<2)return toast('Karşılaştırmak için en az iki ilan seç.');hideTooltip();const items=await Promise.all(selected.map(k=>itemsMap.get(k)||api('/api/item?id='+k))),cheapest=Math.min(...items.map(unit));const row=(label,render,cls='')=>`<tr class="${cls}"><th scope="row">${esc(label)}</th>${items.map(x=>`<td>${render(x)}</td>`).join('')}</tr>`;const effectRows=comparisonBonuses(items).map(k=>row(k.group+' · '+statLabel(k.type),x=>{const b=bonuses(x).find(b=>comparisonBonusKey(x,b)===k.key);if(!b)return '<span class="comparison-missing">Yok</span>';const r=bonusRating(x,b),different=items.some(y=>bonuses(y).find(c=>comparisonBonusKey(y,c)===k.key)?.value!==b.value);return `<span class="bonus-entry ${r.cls}${different?' comparison-different':''}" style="${bonusStyle(b,r)}" data-bonus-type="${b.type}" data-bonus-value="${b.value}" title="${esc(r.label)}">${esc(b.text)}</span>`},'comparison-bonus-row')).join('');$('compare-content').innerHTML=`<div class="modal-pad"><div class="eyebrow">${esc(serverLabel().toLocaleUpperCase('tr'))} · DETAYLI KARŞILAŞTIRMA</div><h2>Farkı detaylarda gör.</h2><p>Fiyatlar adet başına karşılaştırılır. Çerçeveli efsunlarda değer veya özellik farkı vardır.</p>${renderComparisonSummary(items)}<div class="comparison-scroll"><table class="comparison-table"><thead><tr><th scope="col">Özellik</th>${items.map(x=>`<th scope="col" class="comparison-item-heading">${icon(x)}<h3>${esc(title(x))}</h3><span class="comparison-best">${unit(x)===cheapest?'En düşük adet başı fiyat':'Karşılaştırılan ilan'}</span></th>`).join('')}</tr></thead><tbody>${row('Adet başı fiyat',x=>`<strong class="comparison-unit">${esc(moneyText(unit(x)))}</strong>`)}${row('Toplam ilan fiyatı',price)}${row('Listeleyen',seller)}${row('Adet',x=>num(x.Count))}${row('Temel özellikler',comparisonBase)}${row('Element',x=>elementFull(x)||'<span class="comparison-missing">Element yok</span>')}${effectRows}${row('Takılı taş / cevher',x=>stoneIcons(x)||'<span class="comparison-missing">Yok</span>')}${row('Emdirilen ekipman',x=>embeddedCard(x)||'<span class="comparison-missing">Yok</span>')}${row('Ek değerler',x=>equipmentFeatures(x)||'<span class="comparison-missing">Yok</span>')}${row('Son gözlem',x=>esc(date(x.observed)))}</tbody></table></div></div>`;if($('compare-dialog').open)$('compare-dialog').close();$('compare-dialog').showModal()}

function packShop(items){const pages=[];let occupancy=Array(90).fill(false),entries=[];for(const x of items){const size=x.size||1;let pos=-1;for(let i=0;i<90;i++){if(Math.floor(i/10)+size>9)continue;if(Array.from({length:size},(_,s)=>i+s*10).every(p=>!occupancy[p])){pos=i;break}}if(pos<0){pages.push(entries);occupancy=Array(90).fill(false);entries=[];pos=0}for(let s=0;s<size;s++)occupancy[pos+s*10]=true;entries.push({x,col:pos%10+1,row:Math.floor(pos/10)+1,size})}if(entries.length||!pages.length)pages.push(entries);return pages}
async function openShop(sellerName){const requestedServer=selectedServer;hideTooltip();$('shop-content').innerHTML='<div class="empty">Satıcının kayıtları yükleniyor…</div>';if($('shop-dialog').open)$('shop-dialog').close();$('shop-dialog').showModal();try{shopInfo=await api('/api/shop?seller='+encodeURIComponent(sellerName));if(requestedServer!==selectedServer)return;shopInfo.items.forEach(x=>itemsMap.set(x.id,x));shopPages=packShop(shopInfo.items);shopPage=0;renderShop()}catch{$('shop-content').innerHTML='<div class="empty">Satıcı kayıtları yüklenemedi.</div>'}}
function renderShop(){const entries=shopPages[shopPage];$('shop-content').innerHTML=`<div class="shop-top"><div><div class="eyebrow">${esc(serverLabel().toLocaleUpperCase('tr'))} · SATICI PAZARI</div><h2>${svg('shop')}${esc(shopInfo.seller)}</h2><p>${num(shopInfo.total)} kayıtlı ilan · ${num(shopInfo.items.reduce((s,x)=>s+x.Count,0))} toplam adet</p></div></div><div class="shop-body"><div><div class="inventory-frame"><div class="inventory-grid">${entries.map(({x,col,row,size})=>`<button class="inventory-item" style="grid-column:${col};grid-row:${row} / span ${size}" data-shop-select="${x.id}" data-hover="${x.id}" aria-label="${esc(x.Name)} — ${num(x.Count)} adet"><img src="assets/items/${encodeURIComponent(x.icon)}" alt="${esc(x.Name)}"><span class="inventory-quantity">${num(x.Count)}</span>${native(x).element?.grade?`<span class="inventory-grade">+${native(x).element.grade}</span>`:''}</button>`).join('')}</div></div><div class="shop-pages"><button data-shop-page="-1" aria-label="Önceki pazar sayfası" ${shopPage===0?'disabled':''}>←</button><span>PAZAR SAYFASI ${shopPage+1} / ${shopPages.length} · 10 × 9 IZGARA</span><button data-shop-page="1" aria-label="Sonraki pazar sayfası" ${shopPage>=shopPages.length-1?'disabled':''}>→</button></div></div><aside class="shop-side"><p class="shop-selection-help">Özelliklerini görmek için pazardaki eşyaya tıkla.</p><div class="selected-shop-item" id="shop-selection">${entries[0]?shopSelection(entries[0].x):'Satıcı kaydı bulunamadı.'}</div></aside></div><div class="shop-status"><span>${num(shopInfo.total)} İLAN · ${esc(serverLabel().toLocaleUpperCase('tr'))}</span><span>Kaydedilmiş satıcı ilanları; oyundaki özgün dizilim değildir.</span></div>`}
function shopSelection(x){return `<div class="shop-selection-heading">${icon(x)}<div><h4>${esc(title(x))}</h4><div class="item-ident">${num(x.Count)} adet · ${esc(time(x.observed))}</div></div></div>${price(x)}<div class="shop-game-preview">${detailCard(x)}</div><div class="shop-selection-actions"><button class="button gold" data-detail="${x.id}">Tüm eşya detayları ↗</button><button class="button" data-compare="${x.id}">${svg('compare')} Karşılaştır</button></div>`}
function syncNav(){document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view))}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.category!==undefined){clearContextFilters();category=Number(d.category);sub='';view='market';syncNav();renderCategories();load(true)}if(d.sub!==undefined){clearContextFilters();sub=d.sub;renderCategories();load(true)}if(d.query!==undefined){clearContextFilters();$('search').value=d.query;category=0;sub='';view='market';syncNav();renderCategories();load(true)}if(d.view){view=d.view;syncNav();load(true)}if(d.page!==undefined){page=Number(d.page);scrollAfterPage=true;load()}if(d.comparePair){selected=d.comparePair.split('|');renderList();compare()}if(d.detail)details(d.detail);if(d.history)openHistory(d.history);if(d.favorite)toggleFavorite(d.favorite);if(d.compare)toggleCompare(d.compare);if(d.shop)openShop(d.shop);if(d.shopSelect){hideTooltip();$('shop-selection').innerHTML=shopSelection(itemsMap.get(d.shopSelect))}if(d.shopPage){shopPage+=Number(d.shopPage);hideTooltip();renderShop()}if(d.clear){if(d.clear==='category'){clearContextFilters();category=0;sub='';renderCategories()}else if(d.clear==='sub'){clearContextFilters();sub='';renderCategories()}else if(d.clear.startsWith('bonus')){appliedBonuses.splice(Number(d.clear.slice(5)),1);resetBonusDraft()}else $(d.clear).value='';load(true)}if(b.classList.contains('close-dialog')){hideTooltip();b.closest('dialog').close()}});
$('filter-toggle').onclick=()=>{$('filters').hidden=!$('filters').hidden;$('filter-toggle').setAttribute('aria-expanded',String(!$('filters').hidden))};
$('reset').onclick=()=>{for(const k of ['search','player-search',...filterKeys])$(k).value='';appliedBonuses=[];resetBonusDraft();category=0;sub='';renderCategories();load(true)};
let searchTimer;for(const k of [...filterKeys.filter(k=>!['catalogFamily','fishSpecies','fishGrilled','character','consumableEffect','element','stones','grade'].includes(k))])$(k).addEventListener('input',()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>load(true),200)});for(const k of ['character','sort','element','stones','grade','server'])$(k).addEventListener('change',()=>load(true));
$('mobile-subcategory').onchange=()=>{clearContextFilters();sub=$('mobile-subcategory').value;renderCategories();load(true)};$('mobile-category').onchange=()=>{clearContextFilters();category=Number($('mobile-category').value);sub='';renderCategories();load(true)};$('prev').onclick=()=>goToPage(page-1);$('next').onclick=()=>goToPage(page+1);$('clear-compare').onclick=()=>{selected=[];renderList()};for(const k of ['open-compare','compare-nav'])$(k).onclick=compare;$('about').onclick=()=>{$('about-dialog').showModal();hideTooltip()};
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom){hideTooltip();d.close()}}}));document.addEventListener('keydown',e=>{if(e.key==='Escape')hideTooltip();if(e.key==='/'&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)&&!document.querySelector('dialog[open]')){e.preventDefault();$('search').focus()}});
function applyMeta(x,reset=false){meta=x;if(typeof populateSpecialOptions==='function')populateSpecialOptions(x.specialOptions);$('metric-count').textContent=num(x.overall.count);$('metric-types').textContent=num(x.overall.distinctItems);$('metric-sellers').textContent=num(x.overall.sellers);$('metric-updated').textContent=time(x.latest);$('source-time').textContent='Gözlem: '+date(x.latest);$('about-meta').textContent=`${num(x.uniqueRows)} canlı ilan; ${num(x.capturedRows)} kaydedilmiş sürüm. ${num(x.completeDetails)} kayıtta istemci açıklaması var. Son gözlem: ${date(x.latest)}. Veri aktarım zamanı: ${date(x.importedAt)}.`;$('cat-total').textContent=Object.keys(x.categoryTree?.types||{}).length;const ids=new Set(x.statKeys||Object.keys(x.stats));populateBonus($('stat'));renderEconomy();renderCategories();document.title='Metin2Search • '+serverLabel()+' Pazarı';$('economy-server').textContent=serverLabel();return load(reset);}


function renderServers(){const menu=$('server-menu');menu.innerHTML='<span>Türkiye sunucuları</span>'+serverCatalog.map(s=>`<button data-server-id="${s.id}" ${s.available?'':'disabled'} aria-label="${esc(s.name)}${s.available?'':' · Veri bekleniyor'}"><span>${esc(s.name)}<small>${esc(s.clientName.startsWith('[')?s.clientName.match(/^\[([^\]]+)\]/)?.[1]||'':'Türkiye')}</small></span><b>${s.available?(s.id===selectedServer?'✓':'Açık'):'Veri bekleniyor'}</b></button>`).join('')+'<small>İlk kullanılabilir kayıt geldiğinde otomatik açılır.</small>';$('server').innerHTML=serverCatalog.map(s=>`<option value="${s.id}" ${s.available?'':'disabled'}>${esc(s.name)}</option>`).join('');$('server').value=selectedServer;$('server-toggle').querySelector('strong').textContent=serverLabel();if($('sidebar-server'))$('sidebar-server').textContent=serverLabel().toLocaleUpperCase('tr');if(typeof syncMarketHeading==='function')syncMarketHeading()}
async function refreshServers(){const r=await fetch('/api/servers');if(!r.ok)throw Error('Sunucular okunamadı');const data=await r.json();serverCatalog=data.servers;serverFetchTime=Date.now();renderServers();return data}
async function selectServer(id,restore=null){if(serverLoadingFor===id)return;if(!serverCatalog.some(s=>s.id===id&&s.available))return;selectedServer=id;clearPendingUpdate();liveTag='';liveRevision=0;controller?.abort();loadingSequence++;meta=null;category=0;sub='';page=1;selected=[];itemsMap.clear();attachmentHints.clear();view='market';$('search').value='';$('player-search').value='';delete $('search').dataset.exact;delete $('search').dataset.family;delete $('player-search').dataset.exact;for(const k of filterKeys)$(k).value='';appliedBonuses=[];resetBonusDraft();try{favorites=new Set(JSON.parse(localStorage.getItem('m2search-'+id+'-favorites')||'[]'))}catch{favorites=new Set()}document.querySelectorAll('dialog[open]').forEach(d=>d.close());hideTooltip();renderServers();$('server-menu').hidden=true;$('server-toggle').setAttribute('aria-expanded','false');$('list').innerHTML='<div class="empty">Sunucu kayıtları yükleniyor…</div>';const current=id;serverLoadingFor=id;startLiveEvents();try{const x=await api('/api/meta');if(selectedServer!==current)return;liveRevision=x.revision;if(restore)restoreSearch(restore,x);await applyMeta(x,!restore)}catch{$('list').innerHTML='<div class="empty">Sunucu verileri henüz kullanılabilir değil.</div>'}finally{if(serverLoadingFor===id)serverLoadingFor=null}}
document.addEventListener('click',e=>{const button=e.target.closest('[data-server-id]');if(button&&!button.disabled)selectServer(button.dataset.serverId)});
function startLiveEvents(){liveStream?.close();if(document.hidden){setConnectionState('paused');return}const current=selectedServer;setConnectionState('connecting');liveStream=new EventSource('/api/events?server='+encodeURIComponent(current));liveStream.onopen=()=>{if(current===selectedServer)setConnectionState('connected')};liveStream.addEventListener('state',async e=>{if(current!==selectedServer)return;let status;try{status=JSON.parse(e.data)}catch{return}receiveLiveStatus(status);serverCatalog=status.servers;renderServers();if(!meta){if(serverLoadingFor===current)return;const active=serverCatalog.find(s=>s.id===current&&s.available)||serverCatalog.find(s=>s.available);if(active)await selectServer(active.id);return}if(status.available&&status.revision!==liveRevision)showPendingUpdate(status);});liveStream.onerror=()=>{if(current===selectedServer)setConnectionState('offline')}}
document.addEventListener('visibilitychange',()=>{if(document.hidden){liveStream?.close();setConnectionState('paused')}else startLiveEvents()});

refreshServers().then(async()=>{const saved=new URLSearchParams(location.search);const requested=saved.get('server')||selectedServer;const active=serverCatalog.find(s=>s.id===requested&&s.available)||serverCatalog.find(s=>s.available);if(active)await selectServer(active.id,saved);else $('list').innerHTML='<div class="empty">Sunucular için ilk tarama kaydı bekleniyor.</div>';if(!liveStream)startLiveEvents()}).catch(()=>{$('list').innerHTML='<div class="empty">Canlı aktarım sunucusuna bağlanılamadı.</div>';startLiveEvents()});

function setPaginationBusy(busy){$('page-numbers').setAttribute('aria-busy',String(busy));$('prev').disabled=busy||page<=1;$('next').disabled=busy||page>=response.pages;for(const b of $('page-numbers').querySelectorAll('button'))b.disabled=busy;document.querySelector('.pagination')?.classList.toggle('is-loading',busy)}
function goToPage(n){if($('list').getAttribute('aria-busy')==='true'||n===page||n<1||n>response.pages)return;clearTimeout(searchTimer);page=n;scrollAfterPage=true;load()}
$('page-numbers').addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(b)goToPage(Number(b.dataset.page))});



document.addEventListener('click',e=>{const retry=e.target.closest('[data-history-retry]');if(retry)openHistory(retry.dataset.historyRetry,true)});
